import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

// Create axios instance with auth header
const api = axios.create({
  baseURL: "http://localhost:8000",
});

// Add interceptor to include token in requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function BillProcessingPage() {
  const navigate = useNavigate();
  const [selectedFile, setSelectedFile] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState(null);
  const [message, setMessage] = useState("");
  const [profile, setProfile] = useState(null);
  const [dragActive, setDragActive] = useState(false);
  const [showRawText, setShowRawText] = useState(false);
  const [categories, setCategories] = useState([]);

  // Check authentication on component mount
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
      return;
    }
    
    fetchProfile();
    fetchCategories();
  }, [navigate]);

  const fetchProfile = async () => {
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        localStorage.removeItem("token");
        navigate("/login");
      }
    }
  };

  const fetchCategories = async () => {
    try {
      const res = await api.get("/bills/categories");
      setCategories(res.data.categories || []);
    } catch (err) {
      console.error("Error fetching categories:", err);
    }
  };

  const showMessage = (msg, isError = false) => {
    setMessage(msg);
    setTimeout(() => setMessage(""), isError ? 7000 : 5000);
  };

  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    validateAndSetFile(file);
  };

  const validateAndSetFile = (file) => {
    if (!file) return;

    // Check file type
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/bmp', 'image/tiff', 'image/gif', 'application/pdf'];
    if (!allowedTypes.includes(file.type)) {
      showMessage("Please select a valid image file (JPG, PNG, BMP, TIFF, GIF) or PDF.", true);
      return;
    }

    // Check file size (max 10MB)
    const maxSize = 10 * 1024 * 1024; // 10MB
    if (file.size > maxSize) {
      showMessage("File size must be less than 10MB.", true);
      return;
    }

    setSelectedFile(file);
    setResult(null); // Clear previous results
    setMessage("");
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      validateAndSetFile(e.dataTransfer.files[0]);
    }
  };

  const processBill = async () => {
    if (!selectedFile) {
      showMessage("Please select a file first.", true);
      return;
    }

    setIsProcessing(true);
    setMessage("");

    try {
      const formData = new FormData();
      formData.append("file", selectedFile);

      // Step 1: Use the dedicated OCR endpoint (better OCR results)
      const ocrRes = await api.post("/ocr/extract-text", formData, {
        headers: { "Content-Type": "multipart/form-data" },
        timeout: 60000,
      });

      if (!ocrRes.data?.success || !ocrRes.data?.text) {
        showMessage(ocrRes.data?.error || "OCR failed to extract text.", true);
        setResult({ success: false, filename: selectedFile.name, error: ocrRes.data?.error || 'OCR failed' });
        return;
      }

      const extracted = ocrRes.data.text;

      // Step 2: Parse the OCR text into financial data
      const parseRes = await api.post("/bills/parse-text", {
        text: extracted,
        filename: selectedFile.name,
      }, { timeout: 60000 });

      if (parseRes.data?.success) {
        const combined = {
          success: true,
          filename: selectedFile.name,
          file_type: selectedFile.type,
          raw_text: extracted,
          financial_data: parseRes.data.financial_data,
          confidence_score: parseRes.data.confidence_score,
          warnings: parseRes.data.warnings || [],
        };
        setResult(combined);
        showMessage(`Bill processed (OCR-powered)! Confidence: ${(combined.confidence_score * 100).toFixed(1)}%`);
      } else {
        setResult({
          success: false,
          filename: selectedFile.name,
          file_type: selectedFile.type,
          raw_text: extracted,
          error: parseRes.data?.detail || "Failed to parse financial data",
        });
        showMessage(parseRes.data?.detail || "Failed to parse financial data.", true);
      }
    } catch (err) {
      console.error("Bill processing error:", err);
      if (err.response?.status === 401) {
        localStorage.removeItem("token");
        navigate("/login");
      } else if (err.code === 'ECONNABORTED') {
        showMessage("Processing timeout. Please try with a smaller file or better quality image.", true);
      } else {
        showMessage(err.response?.data?.detail || "Error processing bill. Please try again.", true);
      }
    } finally {
      setIsProcessing(false);
    }
  };

  const copyToClipboard = async (text) => {
    try {
      await navigator.clipboard.writeText(text);
      showMessage("Copied to clipboard!");
    } catch (err) {
      console.error("Failed to copy:", err);
      showMessage("Failed to copy to clipboard.", true);
    }
  };

  const exportAsJSON = () => {
    if (!result?.financial_data) return;
    
    const dataStr = JSON.stringify(result.financial_data, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `bill_${result.filename?.split('.')[0] || 'processed'}.json`;
    link.click();
    URL.revokeObjectURL(url);
    showMessage("JSON exported successfully!");
  };

  const clearResults = () => {
    setSelectedFile(null);
    setResult(null);
    setMessage("");
    setShowRawText(false);
    // Reset file input
    const fileInput = document.getElementById("file-input");
    if (fileInput) fileInput.value = "";
  };

  const logout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const goToProfile = () => {
    navigate("/profile");
  };

  const goToOCR = () => {
    navigate("/ocr");
  };

  // Loading spinner component
  const LoadingSpinner = () => (
    <div className="loading-spinner">
      <div className="spinner"></div>
    </div>
  );

  // Get message class based on content
  const getMessageClass = () => {
    if (!message) return "";
    return message.toLowerCase().includes("error") || message.toLowerCase().includes("failed") || message.toLowerCase().includes("timeout")
      ? "message error" 
      : "message success";
  };

  const formatCurrency = (amount, currency = 'USD') => {
    if (amount === null || amount === undefined) return 'N/A';
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency
    }).format(amount);
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return 'N/A';
    try {
      return new Date(dateStr).toLocaleDateString();
    } catch {
      return dateStr;
    }
  };

  const getConfidenceColor = (score) => {
    if (score >= 0.8) return '#28a745'; // Green
    if (score >= 0.6) return '#ffc107'; // Yellow
    return '#dc3545'; // Red
  };

  return (
    <div className="container">
      {/* Header */}
      <div className="bill-header">
        <h1 className="app-title">Bill Processing</h1>
        <div className="user-info-header">
          {profile && (
            <span className="welcome-text">
              Welcome, {profile.name || profile.username || profile.email}!
            </span>
          )}
          <div className="header-buttons">
            <button className="btn btn-secondary" onClick={goToProfile}>
              Profile
            </button>
            <button className="btn btn-danger" onClick={logout}>
              Logout
            </button>
          </div>
        </div>
      </div>

      {/* File Upload Section */}
      <div className="bill-section">
        <h2>Upload Bill or Receipt</h2>
        <p className="section-description">
          Upload an image or PDF of your bill/receipt to automatically extract financial data for expense auditing.
        </p>

        {/* Drag and Drop Area */}
        <div
          className={`file-drop-area ${dragActive ? "drag-active" : ""}`}
          onDragEnter={handleDrag}
          onDragLeave={handleDrag}
          onDragOver={handleDrag}
          onDrop={handleDrop}
        >
          <div className="file-drop-content">
            <div className="file-icon">🧾</div>
            <p>Drag and drop your bill here, or</p>
            <label htmlFor="file-input" className="btn btn-primary file-select-btn">
              Choose File
            </label>
            <input
              id="file-input"
              type="file"
              accept=".jpg,.jpeg,.png,.bmp,.tiff,.gif,.pdf"
              onChange={handleFileSelect}
              style={{ display: "none" }}
            />
          </div>
        </div>

        {/* Selected File Info */}
        {selectedFile && (
          <div className="selected-file-info">
            <div className="file-details">
              <strong>Selected File:</strong> {selectedFile.name}
              <br />
              <strong>Size:</strong> {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
              <br />
              <strong>Type:</strong> {selectedFile.type}
            </div>
            <div className="file-actions">
              <button
                className="btn btn-primary"
                onClick={processBill}
                disabled={isProcessing}
              >
                {isProcessing ? (
                  <>
                    <LoadingSpinner />
                    Processing Bill...
                  </>
                ) : (
                  "Process Bill"
                )}
              </button>
              <button className="btn btn-secondary" onClick={clearResults}>
                Clear
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Results Section */}
      {result && (
        <div className="bill-section">
          <div className="results-header">
            <h2>Processing Results</h2>
            {result.confidence_score && (
              <div className="confidence-badge" style={{ backgroundColor: getConfidenceColor(result.confidence_score) }}>
                Confidence: {(result.confidence_score * 100).toFixed(1)}%
              </div>
            )}
          </div>

          {result.success && result.financial_data ? (
            <div className="financial-data-container">
              {/* Financial Data Cards */}
              <div className="financial-cards">
                <div className="financial-card">
                  <h3>💰 Amount</h3>
                  <div className="amount-large">
                    {formatCurrency(result.financial_data.amount, result.financial_data.currency)}
                  </div>
                </div>

                <div className="financial-card">
                  <h3>📅 Date</h3>
                  <div className="data-value">
                    {formatDate(result.financial_data.date)}
                  </div>
                </div>

                <div className="financial-card">
                  <h3>🏪 Vendor</h3>
                  <div className="data-value">
                    {result.financial_data.vendor || 'Not detected'}
                  </div>
                </div>

                <div className="financial-card">
                  <h3>📂 Category</h3>
                  <div className="data-value category-badge">
                    {result.financial_data.category?.replace('_', ' ').toUpperCase() || 'MISCELLANEOUS'}
                  </div>
                </div>
              </div>

              {/* Detailed Breakdown */}
              <div className="financial-breakdown">
                <h3>Financial Breakdown</h3>
                <div className="breakdown-grid">
                  <div className="breakdown-item">
                    <label>Subtotal:</label>
                    <span>{formatCurrency(result.financial_data.subtotal, result.financial_data.currency)}</span>
                  </div>
                  <div className="breakdown-item">
                    <label>Tax:</label>
                    <span>{formatCurrency(result.financial_data.tax, result.financial_data.currency)}</span>
                  </div>
                  <div className="breakdown-item">
                    <label>Discount:</label>
                    <span>{formatCurrency(result.financial_data.discount, result.financial_data.currency)}</span>
                  </div>
                  <div className="breakdown-item">
                    <label>Currency:</label>
                    <span>{result.financial_data.currency}</span>
                  </div>
                  {result.financial_data.remarks && (
                    <div className="breakdown-item full-width">
                      <label>Remarks:</label>
                      <span>{result.financial_data.remarks}</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Action Buttons */}
              <div className="result-actions">
                <button 
                  className="btn btn-primary" 
                  onClick={() => copyToClipboard(JSON.stringify(result.financial_data, null, 2))}
                >
                  📋 Copy JSON
                </button>
                <button className="btn btn-secondary" onClick={exportAsJSON}>
                  💾 Export JSON
                </button>
                <button 
                  className="btn btn-secondary" 
                  onClick={() => setShowRawText(!showRawText)}
                >
                  {showRawText ? 'Hide' : 'Show'} Raw Text
                </button>
              </div>

              {/* Warnings */}
              {result.warnings && result.warnings.length > 0 && (
                <div className="warnings-section">
                  <h4>⚠️ Processing Warnings</h4>
                  <ul>
                    {result.warnings.map((warning, index) => (
                      <li key={index}>{warning}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          ) : (
            <div className="error-result">
              <h3>❌ Processing Failed</h3>
              <p>{result.error}</p>
            </div>
          )}

          {/* Raw Text Section */}
          {showRawText && result.raw_text && (
            <div className="raw-text-section">
              <h3>Raw Extracted Text</h3>
              <div className="raw-text-content">
                {result.raw_text}
              </div>
            </div>
          )}

          {/* Processing Info */}
          <div className="processing-info">
            <small>
              Processing time: {result.processing_time?.toFixed(2)}s | 
              File: {result.filename} | 
              Type: {result.file_type?.toUpperCase()}
            </small>
          </div>
        </div>
      )}

      {/* Processing Overlay */}
      {isProcessing && (
        <div className="processing-overlay">
          <div className="processing-content">
            <LoadingSpinner />
            <h3>Processing your bill...</h3>
            <p>Extracting text and analyzing financial data...</p>
          </div>
        </div>
      )}

      {/* Message Display */}
      {message && <div className={getMessageClass()}>{message}</div>}

      {/* Instructions */}
      <div className="bill-section instructions">
        <h3>Tips for Better Results</h3>
        <div className="tips-grid">
          <div className="tip-item">
            <h4>📸 Image Quality</h4>
            <p>Use high-resolution images with good lighting and contrast</p>
          </div>
          <div className="tip-item">
            <h4>📄 File Format</h4>
            <p>PNG and PDF files often provide better text extraction</p>
          </div>
          <div className="tip-item">
            <h4>🎯 Focus Areas</h4>
            <p>Ensure total amount, date, and vendor name are clearly visible</p>
          </div>
          <div className="tip-item">
            <h4>📏 Orientation</h4>
            <p>Keep the bill straight and avoid skewed or rotated images</p>
          </div>
        </div>
        
        <div className="supported-categories">
          <h4>Supported Expense Categories</h4>
          <div className="category-tags">
            {categories.map((cat, index) => (
              <span key={index} className="category-tag">
                {cat.label}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default BillProcessingPage;
